SELECT quantilesExactWeighted(0.01, 0.05, 0.1, 0.25, 0.5, 0.75, 0.9, 0.95, 0.99, 0.999, 0.9999)(response_time_ms, request_weight) AS latency_quantiles, sumIf(amount, status = 'paid') - sumIf(amount, status = 'refunded') AS net_amount, uniqCombinedIf(17)(user_id, event_name = 'purchase') / uniqCombined(17)(user_id) AS purchase_share FROM anon.events